tool_calls:
python3 -c "
import os
import re

# Read overrides
overrides = {}
with open('/config/overrides.txt') as f:
    for line in f:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' in line:
            k, v = line.split('=', 1)
            overrides[k.strip()] = v.strip()

# Pattern for KEY=${VALUE:-default} or KEY=${KEY:-default}
# Notice template: DB_HOST=${DB_HOST:-localhost}
# Let's inspect the template lines carefully
results = []
with open('/config/template.env') as f:
    for line in f:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        # Format: KEY=${VAR:-default}
        # e.g. REDIS_URL=${REDIS_URL:-redis://localhost:6379}
        m = re.match(r'^([^=]+)=\$\{[^:]*?:-(.*)\}$', line)
        if m:
            key = m.group(1).strip()
            default_val = m.group(2)
            val = overrides.get(key, default_val)
            results.append(f'{key}={val}')
        else:
            print('Could not match line:', line)

os.makedirs('/app', exist_ok=True)
output_content = '\n'.join(results) + '\n'
with open('/app/.env', 'w') as f:
    f.write(output_content)

print(output_content, end='')
"

